package com.searchplatform.indexer;

import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

@RestController
@RequestMapping("/api/v2/index")
public class DocumentIndexController {

    private final IndexingPipeline pipeline;
    private final ContentValidator validator;

    public DocumentIndexController(IndexingPipeline pipeline, ContentValidator validator) {
        this.pipeline = pipeline;
        this.validator = validator;
    }

    @PostMapping("/batch-upload")
    public Map<String, Object> batchUpload(
            @RequestParam("archive") MultipartFile archive,
            @RequestParam(value = "tenant", required = true) String tenantId,
            HttpServletRequest request) throws Exception {

        String authToken = request.getHeader("X-Service-Auth");
        if (!validateServiceToken(authToken, tenantId)) {
            throw new SecurityException("Invalid service authentication");
        }

        if (archive.getSize() > 50 * 1024 * 1024) {
            throw new IllegalArgumentException("Archive exceeds 50MB limit");
        }

        String contentHash = computeSHA256(archive.getBytes());
        Path stagingDir = createStagingDirectory(tenantId, contentHash);

        try {
            int extracted = extractAndValidate(archive.getInputStream(), stagingDir, tenantId);
            List<String> indexed = pipeline.processDirectory(stagingDir, tenantId);
            return Map.of("status", "success", "documents_indexed", indexed.size(),
                         "batch_id", contentHash);
        } finally {
            deleteRecursive(stagingDir);
        }
    }

    private int extractAndValidate(InputStream input, Path stagingDir, String tenantId) throws Exception {
        int count = 0;
        long totalSize = 0;
        final long MAX_TOTAL = 100 * 1024 * 1024;
        final int MAX_ENTRIES = 500;

        try (ZipInputStream zis = new ZipInputStream(input)) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                if (count >= MAX_ENTRIES) {
                    throw new IllegalArgumentException("Too many entries in archive");
                }

                String entryName = entry.getName();
                if (entry.isDirectory()) {
                    zis.closeEntry();
                    continue;
                }

                Path resolvedPath = resolveEntryPath(stagingDir, entryName);
                String extension = getExtension(resolvedPath.getFileName().toString());

                if (!validator.isAllowedExtension(extension)) {
                    zis.closeEntry();
                    continue;
                }

                Files.createDirectories(resolvedPath.getParent());

                byte[] buffer = new byte[8192];
                long entrySize = 0;
                try (OutputStream out = Files.newOutputStream(resolvedPath)) {
                    int len;
                    while ((len = zis.read(buffer)) > 0) {
                        entrySize += len;
                        totalSize += len;
                        if (totalSize > MAX_TOTAL) {
                            throw new IllegalArgumentException("Extracted content exceeds size limit");
                        }
                        out.write(buffer, 0, len);
                    }
                }

                if (!validator.validateContent(resolvedPath, extension)) {
                    Files.deleteIfExists(resolvedPath);
                    continue;
                }

                count++;
                zis.closeEntry();
            }
        }
        return count;
    }

    private Path resolveEntryPath(Path stagingDir, String entryName) {
        // Normalize the entry name to prevent directory traversal
        String normalized = entryName.replace('\\', '/');
        String[] parts = normalized.split("/");
        Path resolved = stagingDir;
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) continue;
            if (part.equals("..")) continue;
            resolved = resolved.resolve(part);
        }
        // Verify the resolved path is within staging directory
        if (!resolved.normalize().startsWith(stagingDir.normalize())) {
            throw new SecurityException("Path traversal detected: " + entryName);
        }
        return resolved;
    }

    private boolean validateServiceToken(String token, String tenantId) {
        if (token == null || token.isEmpty()) return false;
        // In production, validates against K8s service account token
        return token.length() >= 32 && token.startsWith("svc-");
    }

    private Path createStagingDirectory(String tenantId, String hash) throws IOException {
        String safeTenant = tenantId.replaceAll("[^a-zA-Z0-9_-]", "");
        Path dir = Paths.get("/tmp/indexer-staging", safeTenant, hash);
        Files.createDirectories(dir);
        return dir;
    }

    private String computeSHA256(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] digest = md.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    private String getExtension(String filename) {
        int dot = filename.lastIndexOf('.');
        return dot >= 0 ? filename.substring(dot + 1).toLowerCase() : "";
    }

    private void deleteRecursive(Path dir) throws IOException {
        if (Files.exists(dir)) {
            Files.walk(dir).sorted(Comparator.reverseOrder()).map(Path::toFile).forEach(File::delete);
        }
    }
}

@Service
class ContentValidator {

    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(
        "pdf", "doc", "docx", "txt", "html", "xml", "json", "csv", "rtf", "odt"
    );

    private static final Map<String, byte[]> MAGIC_BYTES = Map.of(
        "pdf", new byte[]{0x25, 0x50, 0x44, 0x46},
        "doc", new byte[]{(byte)0xD0, (byte)0xCF, 0x11, (byte)0xE0}
    );

    public boolean isAllowedExtension(String ext) {
        return ALLOWED_EXTENSIONS.contains(ext.toLowerCase());
    }

    public boolean validateContent(Path file, String extension) throws IOException {
        if (Files.size(file) == 0) return false;
        if (Files.size(file) > 20 * 1024 * 1024) return false;

        byte[] header = new byte[16];
        int headerRead;
        try (InputStream is = Files.newInputStream(file)) {
            // readNBytes reads until the buffer is filled or EOF, avoiding
            // partial-read issues where trailing bytes remain zero.
            headerRead = is.readNBytes(header, 0, header.length);
        }

        // For binary formats, verify magic bytes
        if (MAGIC_BYTES.containsKey(extension)) {
            byte[] expected = MAGIC_BYTES.get(extension);
            // If we could not read enough bytes to cover the expected magic, reject.
            if (headerRead < expected.length) return false;
            for (int i = 0; i < expected.length; i++) {
                if (header[i] != expected[i]) return false;
            }
        }

        // For text formats, check for embedded executable content
        if (isTextFormat(extension)) {
            return !containsExecutableMarkers(file);
        }

        return true;
    }

    private boolean isTextFormat(String ext) {
        return Set.of("txt", "html", "xml", "json", "csv", "rtf").contains(ext);
    }

    private boolean containsExecutableMarkers(Path file) throws IOException {
        String content = Files.readString(file);
        // Check for script injection in text documents
        String lower = content.toLowerCase();
        return lower.contains("<script") || lower.contains("javascript:") ||
               lower.contains("vbscript:") || lower.contains("data:text/html");
    }
}

@Service
class IndexingPipeline {

    private final ConcurrentHashMap<String, List<String>> tenantIndex = new ConcurrentHashMap<>();

    private static final Set<String> SUPPORTED_FORMATS = Set.of(
        "pdf", "doc", "docx", "txt", "html", "xml", "json", "csv", "rtf", "odt"
    );

    public List<String> processDirectory(Path dir, String tenantId) throws IOException {
        List<String> indexed = new ArrayList<>();
        Files.walk(dir)
            .filter(Files::isRegularFile)
            .forEach(file -> {
                try {
                    String docId = indexDocument(file, tenantId);
                    if (docId != null) indexed.add(docId);
                } catch (Exception e) {
                    // Log and continue
                }
            });
        return indexed;
    }

    private String indexDocument(Path file, String tenantId) throws Exception {
        String ext = getExtension(file.getFileName().toString());

        if (!SUPPORTED_FORMATS.contains(ext)) {
            return null;
        }

        String content = defaultParse(file, ext);

        if (content == null || content.isBlank()) return null;

        String docId = UUID.randomUUID().toString();
        tenantIndex.computeIfAbsent(tenantId, k -> new ArrayList<>()).add(docId);
        return docId;
    }

    private String defaultParse(Path file, String ext) throws IOException {
        return Files.readString(file);
    }

    private String getExtension(String filename) {
        int dot = filename.lastIndexOf('.');
        return dot >= 0 ? filename.substring(dot + 1).toLowerCase() : "";
    }
}
